package com.game_manager.gm.machine;import com.game_manager.gm.common.error.ApplicationException;import com.game_manager.gm.gamingsession.*;import com.game_manager.gm.gamingsession.command.*;import java.time.*;import java.util.*;import lombok.RequiredArgsConstructor;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;
@Service@RequiredArgsConstructor public class StationEnforcementProjectionService {private final StationClientEnforcementRepository states;private final StationReconciliationAuditRepository audits;private final Clock clock;@org.springframework.beans.factory.annotation.Autowired private DevelopmentStations development;@org.springframework.beans.factory.annotation.Autowired private GamingSessionRepository sessions;
 @Transactional(propagation=Propagation.MANDATORY)public void commandIssued(GamingSession session,StationCommandType type,long sequence){commandIssued(session.getResourceId(),session.getId(),type.name(),sequence);}
 @Transactional(propagation=Propagation.MANDATORY)public void commandIssued(UUID stationId,UUID sessionId,String commandType,long sequence){StationCommandType type=StationCommandType.valueOf(commandType);StationClientEnforcement state=state(stationId);StationEnforcementStatus previous=state.getEnforcementStatus();state.setSessionId(sessionId);state.setLastCommandSequence(Math.max(state.getLastCommandSequence(),sequence));state.setEnforcementStatus(type==StationCommandType.SESSION_TERMINATED||type==StationCommandType.FORCE_LOCK?StationEnforcementStatus.LOCK_PENDING:StationEnforcementStatus.UNLOCKED);state.setReason(type.name());states.save(state);audit(state,sessionId,null,"COMMAND_ISSUED",previous,sequence,type.name());}
 @Transactional public void leaseIssued(MachinePrincipal machine,UUID leaseId,UUID sessionId,Instant expiresAt,long configVersion,long cursor){StationClientEnforcement state=state(machine.stationId());state.setIdentityId(machine.identityId());if(sessionId!=null)state.setSessionId(sessionId);state.setLastLeaseId(leaseId);state.setLastLeaseExpiresAt(expiresAt);state.setLastConfigVersion(Math.max(state.getLastConfigVersion(),configVersion));state.setLastCommandSequence(Math.max(state.getLastCommandSequence(),cursor));state.setClientReportedAt(clock.instant());states.save(state);}
 @Transactional public void heartbeat(MachinePrincipal machine,StationEnforcementStatus reported,UUID sessionId,UUID leaseId,long configVersion,long cursor) {
  boolean simulated=reported==StationEnforcementStatus.DEV_READY || reported==StationEnforcementStatus.DEV_ACTIVE;
  if(simulated && !development.localEnvironment())throw new ApplicationException(HttpStatus.CONFLICT,"Development readiness requires the local backend profile");
  if(simulated && !development.enabled(machine.stationId()))throw new ApplicationException(HttpStatus.CONFLICT,"Development station is not explicitly enabled in the local backend");
  StationClientEnforcement state=state(machine.stationId());
  if(simulated) {
   if(leaseId==null || !leaseId.equals(state.getLastLeaseId()) || state.getLastLeaseExpiresAt()==null || !state.getLastLeaseExpiresAt().isAfter(clock.instant()))
    throw new ApplicationException(HttpStatus.CONFLICT,"Development readiness requires the current signed lease");
   if(cursor<state.getLastCommandSequence())throw new ApplicationException(HttpStatus.CONFLICT,"Development command cursor is stale");
   var active=sessions.findByResourceIdAndStatus(machine.stationId(),GamingSessionStatus.ACTIVE);
   if(reported==StationEnforcementStatus.DEV_READY && active.isPresent())throw new ApplicationException(HttpStatus.CONFLICT,"Development session state changed; refresh the signed lease");
   if(reported==StationEnforcementStatus.DEV_ACTIVE && (active.isEmpty() || !active.get().getId().equals(sessionId)))
    throw new ApplicationException(HttpStatus.CONFLICT,"Development session state changed; refresh the signed lease");
   if(!machine.identityId().equals(state.getIdentityId()) || configVersion!=state.getLastConfigVersion())
    throw new ApplicationException(HttpStatus.CONFLICT,"Development readiness requires the current signed lease");
  }
  state.setIdentityId(machine.identityId());state.setClientReportedAt(clock.instant());
  state.setLastCommandSequence(Math.max(state.getLastCommandSequence(),cursor));state.setLastConfigVersion(Math.max(state.getLastConfigVersion(),configVersion));
  if(leaseId!=null)state.setLastLeaseId(leaseId);
  if(sessionId!=null)state.setSessionId(sessionId);
  if(reported!=null && (reported!=StationEnforcementStatus.LOCKED || state.getSessionId()==null && state.getLastCommandSequence()==0))state.setEnforcementStatus(reported);
  if(simulated)state.setReason(reported==StationEnforcementStatus.DEV_READY?"Development idle; Windows protection is simulated":"Development session; Windows protection is simulated");
  states.save(state);
 }

 @Transactional public Instant lockAck(MachinePrincipal machine,UUID sessionId,long sequence,UUID leaseId,String reason){if(development.enabled(machine.stationId()))throw new ApplicationException(HttpStatus.CONFLICT,"Development stations cannot confirm physical Windows lock");StationClientEnforcement state=state(machine.stationId());if(sequence!=state.getLastCommandSequence())throw new ApplicationException(HttpStatus.CONFLICT,"Lock acknowledgement is stale; acknowledge the current lock command");if(state.getSessionId()!=null&&!state.getSessionId().equals(sessionId))throw new ApplicationException(HttpStatus.CONFLICT,"Lock acknowledgement does not match enforcement projection");StationEnforcementStatus previous=state.getEnforcementStatus();Instant now=clock.instant();state.setIdentityId(machine.identityId());state.setSessionId(sessionId);state.setLastCommandSequence(Math.max(state.getLastCommandSequence(),sequence));if(leaseId!=null)state.setLastLeaseId(leaseId);state.setEnforcementStatus(StationEnforcementStatus.LOCKED);state.setLastLockAckAt(now);state.setClientReportedAt(now);state.setReason(reason);states.save(state);audit(state,sessionId,null,"LOCK_ACK",previous,sequence,reason);return now;}
 @Transactional public void operatorRecovery(UUID stationId,UUID sessionId,UUID actorId,String action,long sequence,String details){if(development.enabled(stationId)&&action.equals("OPERATOR_RECOVERY"))throw new ApplicationException(HttpStatus.CONFLICT,"Development stations cannot confirm physical Windows lock");StationClientEnforcement state=state(stationId);StationEnforcementStatus previous=state.getEnforcementStatus();state.setSessionId(sessionId);state.setLastCommandSequence(Math.max(state.getLastCommandSequence(),sequence));state.setEnforcementStatus(action.equals("OPERATOR_RECOVERY")?StationEnforcementStatus.LOCKED:StationEnforcementStatus.LOCK_PENDING);state.setReason(details);if(action.equals("OPERATOR_RECOVERY"))state.setLastLockAckAt(clock.instant());states.save(state);audit(state,sessionId,actorId,action,previous,sequence,details);}
 @Transactional(readOnly=true)public boolean safeForNewSession(UUID stationId){return states.findById(stationId).map(value->value.getEnforcementStatus()==StationEnforcementStatus.LOCKED || development.enabled(stationId) && value.getEnforcementStatus()==StationEnforcementStatus.DEV_READY && value.getLastLeaseExpiresAt()!=null && value.getLastLeaseExpiresAt().isAfter(clock.instant()) && sessions.findByResourceIdAndStatus(stationId,GamingSessionStatus.ACTIVE).isEmpty()).orElse(false);}

 private StationClientEnforcement state(UUID stationId){return states.findById(stationId).orElseGet(()->{StationClientEnforcement value=new StationClientEnforcement();value.setStationId(stationId);return value;});}
 private void audit(StationClientEnforcement state,UUID sessionId,UUID actor,String action,StationEnforcementStatus previous,Long sequence,String details){StationReconciliationAudit event=new StationReconciliationAudit();event.setStationId(state.getStationId());event.setSessionId(sessionId);event.setActorId(actor);event.setAction(action);event.setPreviousStatus(previous==null?null:previous.name());event.setResultingStatus(state.getEnforcementStatus().name());event.setCommandSequence(sequence);event.setDetails(details);event.setOccurredAt(clock.instant());audits.save(event);}
}
